import { spawn } from "node:child_process";
const cfg = JSON.parse((await import("node:fs")).readFileSync("/harness-state/claude/.claude.json","utf8")).mcpServers.gbrain;
const p = spawn(cfg.command, cfg.args, { stdio: ["pipe","pipe","pipe"], env: { ...process.env, ...cfg.env } });
let buf = "", pending = new Map(), id = 0;
p.stdout.on("data", d => { buf += d; let i; while ((i = buf.indexOf("\n")) >= 0) { const line = buf.slice(0,i); buf = buf.slice(i+1); if (!line.trim()) continue; const m = JSON.parse(line); if (m.id != null && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } } });
const rpc = (method, params) => new Promise(r => { const n = ++id; pending.set(n, r); p.stdin.write(JSON.stringify({ jsonrpc: "2.0", id: n, method, params }) + "\n"); });
const text = r => r.error ? "ERROR " + JSON.stringify(r.error) : (r.result.content||[]).map(c=>c.text).join("\n").slice(0, 700);
const init = await rpc("initialize", { protocolVersion: "2025-06-18", capabilities: {}, clientInfo: { name: "install-check", version: "1" } });
console.log("server:", JSON.stringify(init.result?.serverInfo));
p.stdin.write(JSON.stringify({ jsonrpc: "2.0", method: "notifications/initialized" }) + "\n");
const tools = await rpc("tools/list", {});
console.log("tools:", tools.result.tools.map(t => t.name).join(", "));
const [, , mode, ...rest] = process.argv;
for (const call of JSON.parse(rest.join(" "))) { console.log(`== ${call.name} ${JSON.stringify(call.arguments)}`); console.log(text(await rpc("tools/call", call))); }
p.kill();
EOF
